unsafe fn updateHashChain(
    mut hash: *mut Hash,
    mut wpos: size_t,
    mut hashval: c_uint,
    mut numzeros: c_ushort,
) {
    let hash_ref = unsafe { &mut *hash }; // SAFETY: caller provides a valid, writable pointer to Hash for the duration of this function.

    let wpos_i = wpos as isize;
    let hash_i = hashval as isize;
    let zeros_i = numzeros as isize;
    let wpos_c = wpos as c_int;

    unsafe {
        // SAFETY: all pointer arithmetic and dereferences mirror the original function's accesses and rely on the same caller guarantees that the Hash member pointers are valid for these indices.
        *hash_ref.val.offset(wpos_i) = hashval as c_int;

        let head_ptr = hash_ref.head.offset(hash_i);
        let head_val = *head_ptr;
        if head_val != -1 {
            *hash_ref.chain.offset(wpos_i) = head_val as c_ushort;
        }
        *head_ptr = wpos_c;

        *hash_ref.zeros.offset(wpos_i) = numzeros;

        let headz_ptr = hash_ref.headz.offset(zeros_i);
        let headz_val = *headz_ptr;
        if headz_val != -1 {
            *hash_ref.chainz.offset(wpos_i) = headz_val as c_ushort;
        }
        *headz_ptr = wpos_c;
    }
}

